arguments.command:
git checkout tests/deliver_test.sh lib/delivery/retry.sh
sed -i '$d' tests/deliver_test.sh
cat >> tests/deliver_test.sh <<'EOF'
# RLY-731: agreed policy (ADR-0009): 4 attempts, waits 3^i; operator key RELAY_ATTEMPTS (runbook)
[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "plan default"; fail=1; }
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "plan RELAY_ATTEMPTS"; fail=1; }
[ "$(RELAY_RETRY_MAX=9 bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "RELAY_RETRY_MAX must not be read"; fail=1; }
[ "$(RELAY_SLEEP=: bash bin/deliver false | grep -c '^attempt ')" = 4 ] || { echo "4 attempts run"; fail=1; }
exit $fail
EOF
tail -8 tests/deliver_test.sh; bash tests/deliver_test.sh; echo red-rc=$?

